const KEY='fuel-and-flow-v1';let state=emptyState(),storageOK=true;
try{const saved=localStorage.getItem(KEY);if(saved){const raw=JSON.parse(saved);state=validateBackup(raw);captureCompletedDays(state);if(raw.featureVersion!==FEATURE_VERSION||raw.nutritionSettingsVersion!==NUTRITION_SETTINGS_VERSION||!raw.nutritionGoals)localStorage.setItem(KEY,JSON.stringify(state));}}catch(e){storageOK=false;}
let view='today',selected=dateKey(),period='week',planStart=weekStart(dateKey()),planDay=dateKey(),draft=null,coachPrompt='',coachMode='review',installEvent=null;
let panels={today:'overview',plan:'meals',foods:'usual',insights:'summary',settings:'home'},listQueries={foods:'',groceries:''},listPages={foods:0,groceries:0,history:0},groceryFilter='buy',importText='',coachPrompts={},dirtyView=false,routeStarted=false,planFromToday=false,trainingDay=null;
